import {courses} from './data.js?v=20261014e';
import {lessons} from './lessons.js?v=20261014e';
import {escapeHTML as e} from './core.js?v=20261014e';
import {newNote,findNotes,deltaText,cleanDelta,legacyNotes,PALETTE,HIGHLIGHTS,referencedImages} from './notebook-core.js?v=20261014e';
import {loadScript} from './study-space.js?v=20261014-nologin1';
let query='',course='',archived=false,reviewing=false,reviewIndex=0,revealed=false,editor=null,unmount=()=>{},mountNumber=0;
const stamps=x=>new Intl.DateTimeFormat('th-TH',{dateStyle:'medium',timeStyle:'short'}).format(new Date(x));
const choices=value=>`<option value="">บันทึกทั่วไป</option>${courses.map(c=>`<option value="${c.id}" ${value===c.id?'selected':''}>${c.id} · ${e(c.title)}</option>`).join('')}`;
function heading(title,detail){return `<div class="page-heading"><div><div class="eyebrow">MY LEARNING NOTEBOOK</div><h1>${title}</h1><p>${detail}</p></div></div>`;}
function status(space){const i=space.info();return `<div class="notebook-status"><span class="status-dot"></span><span data-sync-status>${e(i.status)}</span><a href="#account">ข้อมูลและเปิดบนอีกเครื่อง →</a></div>`;}
export function notebookPage(space,progress){
 const book=space.notebook(),items=findNotes(book,{query,course,archived});
 if(reviewing){const deck=findNotes(book,{course}).filter(n=>n.question.trim()&&n.answer.trim());const n=deck[reviewIndex%deck.length];return `${heading('ทบทวนจากโน้ตของฉัน','นึกคำตอบก่อนเปิดดู ใช้สิ่งที่คุณจดมาเตรียมสอบ')}<button class="button secondary" data-action="nb-review-close">← กลับสมุดจด</button>${n?`<section class="panel note-recall"><span class="badge">${e(n.course||'ทั่วไป')} · ${reviewIndex%deck.length+1}/${deck.length}</span><h2>${e(n.question)}</h2>${revealed?`<div class="recall-answer">${e(n.answer)}</div><button class="button primary" data-action="nb-review-next">ข้อถัดไป →</button>`:'<button class="button primary" data-action="nb-reveal">เปิดคำตอบ</button>'}<a href="#note/${n.id}" class="text-link">เปิดโน้ตต้นทาง →</a></section>`:'<div class="panel empty"><h2>ยังไม่มีคำถามจากโน้ต</h2><p>เปิดหน้าโน้ต แล้วเติม “คำถามทวนความจำ” กับ “คำตอบของฉัน” ก่อน</p></div>'}`;}
 const old=lessons.filter(l=>progress.notes[l.id]?.trim());
 return `${heading('สมุดจดของฉัน','จดระหว่างเรียน ไฮไลต์ประเด็นสำคัญ เก็บรูป แล้วกลับมาทบทวน')}<div class="notebook-actions"><button class="button primary" data-action="nb-new">＋ สร้างหน้าโน้ต</button><button class="button secondary" data-action="nb-review">ทบทวนจากโน้ต</button><button class="button secondary" data-action="nb-export">ส่งออกโน้ตพร้อมรูป</button><label class="button secondary">นำเข้าสมุดจด<input hidden type="file" id="notebook-import" accept=".json,application/json"></label></div>${status(space)}<div class="notebook-filters"><label class="field">ค้นหาโน้ต<input id="notebook-search" type="search" placeholder="หัวข้อ เนื้อหา หรือแท็ก…" value="${e(query)}"></label><label class="field">รายวิชา<select id="notebook-course"><option value="">ทุกวิชา</option>${courses.map(c=>`<option ${course===c.id?'selected':''}>${c.id}</option>`).join('')}</select></label><button class="button ${archived?'primary':'secondary'}" data-action="nb-archive-filter">${archived?'ดูโน้ตที่เก็บเข้าคลังอยู่':'เปิดคลังโน้ต'}</button></div><div id="notebook-results">${noteCards(items)}</div>${old.length?`<details class="panel legacy-notes"><summary>บันทึกข้อความเดิมจากบทเรียน (${old.length})</summary><p>ต้นฉบับยังอยู่ครบ สามารถคัดลอกเป็นหน้าโน้ตที่จัดสีและแทรกรูปได้</p><button class="button secondary" data-action="nb-import-legacy">คัดลอกบันทึกเดิมเข้าสมุดจด</button>${old.map(l=>`<article><h3>${l.course} · ${e(l.title)}</h3><p class="note-preview">${e(progress.notes[l.id])}</p><a href="#lesson/${l.id}">เปิดบทเรียน →</a></article>`).join('')}</details>`:''}`;
}
export function noteCards(items){return items.length?`<div class="notebook-grid">${items.map(n=>`<a class="note-card" href="#note/${n.id}"><div class="note-card-top"><span class="badge">${e(n.course||'บันทึกทั่วไป')}</span>${n.pinned?'<span>★ ปักหมุด</span>':''}</div><h2>${e(n.title)}</h2><p>${e(deltaText(n.delta).trim().slice(0,150)||'เริ่มเขียนความเข้าใจของคุณ…')}</p><div class="note-tags">${e(n.tags)}</div><small>แก้ไข ${stamps(n.updatedAt)} · ${n.delta.ops.filter(o=>o.insert?.studyImage).length} รูป</small></a>`).join('')}</div>`:'<section class="panel empty"><h2>พื้นที่สำหรับความเข้าใจของคุณ</h2><p>สร้างโน้ตจากคำบรรยาย ตำรา หรือเรื่องที่ยังสงสัยได้เลย</p><button class="button primary" data-action="nb-new">สร้างโน้ตหน้าแรก</button></section>';}
export function notePage(space,id){const n=space.notebook().notes.find(x=>x.id===id);if(!n)return '<section class="panel"><h1>ไม่พบหน้าโน้ต</h1><a href="#notes">กลับสมุดจด</a></section>';
 return `<div class="note-page"><a class="back-link" href="#notes">← สมุดจดของฉัน</a>${status(space)}<div class="note-head"><label class="field note-title-field">ชื่อหน้าโน้ต<input id="note-title" maxlength="160" value="${e(n.title)}" placeholder="ชื่อโน้ต"></label><div class="button-row"><button class="button secondary" data-action="nb-pin" data-id="${id}">${n.pinned?'★ ปักหมุดแล้ว':'☆ ปักหมุด'}</button><button class="button secondary" data-action="nb-print">พิมพ์ / PDF</button><button class="button secondary" data-action="nb-archive" data-id="${id}">${n.archived?'นำกลับมาใช้':'เก็บเข้าคลัง'}</button></div></div><div class="note-meta"><label class="field">วิชา<select id="note-course">${choices(n.course)}</select></label><label class="field">เชื่อมกับบทเรียน<select id="note-lesson"><option value="">ไม่ระบุบทเรียน</option>${lessons.filter(l=>!n.course||l.course===n.course).map(l=>`<option value="${l.id}" ${n.lesson===l.id?'selected':''}>${l.course} · ${e(l.title)}</option>`).join('')}</select></label><label class="field">แท็ก<input id="note-tags" maxlength="250" value="${e(n.tags)}" placeholder="เช่น อาจารย์เน้น, ยังไม่แม่น"></label></div>
 <div class="note-editor-shell"><div class="note-tools" id="note-tools"><div class="note-tool-row"><strong>สีตัวอักษร</strong>${PALETTE.map(c=>`<button type="button" class="color-swatch" style="--swatch:${c}" data-note-color="${c}" aria-label="สีตัวอักษร ${c}" title="สีตัวอักษร ${c}"></button>`).join('')}<strong>ไฮไลต์</strong>${HIGHLIGHTS.map(c=>`<button type="button" class="color-swatch" style="--swatch:${c}" data-note-bg="${c}" aria-label="ไฮไลต์ ${c}" title="ไฮไลต์ ${c}"></button>`).join('')}<button type="button" class="note-tool-button" data-note-bg="clear">ลบไฮไลต์</button></div><div class="note-tool-row"><button type="button" class="button secondary" id="insert-note-image">＋ แทรกรูป</button><button type="button" class="note-tool-button" id="note-undo">↶ ย้อนกลับ</button><button type="button" class="note-tool-button" id="note-redo">↷ ทำซ้ำ</button><span>วางรูปจากคลิปบอร์ดหรือลากรูปมาวางได้ · ไม่เกิน 5 MB/รูป</span><input hidden type="file" id="note-image-file" accept="image/png,image/jpeg,image/webp,image/gif" multiple></div></div><div id="rich-note-editor" aria-label="พื้นที่จดโน้ต"><p>กำลังเปิดเครื่องมือจดโน้ต…</p></div><p class="note-save-state" id="rich-note-status" role="status">โน้ตจะบันทึกใน Supabase อัตโนมัติเมื่อแก้ไข</p></div>
 <div class="note-study-tools"><section class="panel"><span class="eyebrow">ACTIVE RECALL</span><h2>ทำโน้ตหน้านี้ให้ช่วยติว</h2><label class="field">คำถามทวนความจำ<textarea id="note-question" rows="3" maxlength="4000" placeholder="ถ้าไม่เปิดหนังสือ ฉันตอบเรื่องนี้ได้ไหม?">${e(n.question)}</textarea></label><label class="field">คำตอบของฉัน<textarea id="note-answer" rows="4" maxlength="10000" placeholder="สรุปคำตอบด้วยภาษาของตัวเอง">${e(n.answer)}</textarea></label><button class="button secondary" data-action="nb-review">เริ่มทบทวนจากโน้ต</button></section><aside class="panel"><h2>จดแล้วเรียนต่อ</h2><p>ลองแบ่งโน้ตเป็น “สิ่งที่เข้าใจ”, “อาจารย์เน้น”, “สิ่งที่ยังสงสัย” แล้วใช้สีไฮไลต์เฉพาะคำสำคัญ</p>${n.lesson?`<a class="button secondary" href="#lesson/${n.lesson}">เปิดบทเรียนที่เกี่ยวข้อง →</a>`:''}${lessons.some(l=>l.course===n.course)?`<a class="button secondary" href="#prep/${n.course}">ฝึกข้อสอบ ${n.course} →</a>`:''}<a href="https://ondemand.ru.ac.th/" class="text-link" target="_blank" rel="noopener noreferrer">เปิด RU on Demand ↗</a><p class="quiet-note">รูปและโน้ตจะซิงก์เมื่อเข้าสู่ระบบ ส่วนไฟล์ส่งออกพร้อมรูปช่วยสำรองข้อมูลอีกชุดได้</p></aside></div></div>`;
}
export function destroyEditor(){mountNumber++;unmount();unmount=()=>{};editor=null;}
export async function mountEditor(space,id){
 destroyEditor();const token=mountNumber,n=space.notebook().notes.find(x=>x.id===id);if(!n)return;
 const urls=[],listeners=[];const bind=(el,event,fn,opts)=>{el?.addEventListener(event,fn,opts);listeners.push(()=>el?.removeEventListener(event,fn,opts));};
 unmount=()=>{listeners.forEach(f=>f());urls.forEach(u=>URL.revokeObjectURL(u));};
 const say=(text,bad=false)=>{const s=document.getElementById('rich-note-status');if(s){s.textContent=text;s.classList.toggle('error',bad);}};
 try{
  await loadScript('./vendor/quill-2.0.3.js');if(token!==mountNumber)return;
  const Q=globalThis.Quill,Base=Q.import('blots/block/embed');
  if(!Q.imports['formats/studyImage']){class StudyImage extends Base{static blotName='studyImage';static tagName='img';static className='study-note-image';static create(id){const el=super.create();el.dataset.imageId=id;el.alt='รูปในโน้ต';el.loading='lazy';return el;}static value(el){return el.dataset.imageId;}}Q.register(StudyImage);}
  const host=document.getElementById('rich-note-editor');host.innerHTML='';
  const q=new Q(host,{theme:'snow',placeholder:'เขียนสรุปด้วยคำของตัวเอง…',formats:['bold','italic','underline','strike','header','list','blockquote','align','color','background','link','studyImage'],modules:{toolbar:[[{header:[1,2,3,false]}],['bold','italic','underline','strike'],[{list:'ordered'},{list:'bullet'},{list:'check'}],['blockquote','link','clean']],history:{delay:800,maxStack:100,userOnly:true}}});editor=q;q.setContents(cleanDelta(n.delta),'silent');q.history.clear();q.root.setAttribute('aria-label','เนื้อหาโน้ต จัดรูปแบบและแทรกรูปได้');q.root.setAttribute('spellcheck','false');
  const labels={bold:'ตัวหนา',italic:'ตัวเอียง',underline:'ขีดเส้นใต้',strike:'ขีดฆ่า',list:'รายการ',blockquote:'ข้อความอ้างอิง',link:'เพิ่มลิงก์',clean:'ล้างรูปแบบ'};host.previousElementSibling?.querySelectorAll('button').forEach(b=>{const k=[...b.classList].find(c=>c.startsWith('ql-'))?.slice(3);b.title=labels[k]||'จัดข้อความ';b.setAttribute('aria-label',b.title);});

  // saveNotebook validates into a new object. Always update the current note reference.
  const persist=()=>{const live=space.notebook().notes.find(x=>x.id===id);if(!live)return;try{live.delta=cleanDelta(q.getContents());live.updatedAt=new Date().toISOString();const ok=space.saveNotebook(space.notebook());say(ok?space.info().status:'ยังไม่บันทึกใน Supabase',!ok);}catch(err){say(err.message,true);}};
  q.on('text-change',persist);listeners.push(()=>q.off('text-change',persist));
  async function hydrate(){for(const img of q.root.querySelectorAll('img[data-image-id]')){if(img.getAttribute('src'))continue;try{const blob=await space.image(img.dataset.imageId);if(token!==mountNumber)return;const url=URL.createObjectURL(blob);urls.push(url);img.src=url;}catch{img.alt='โหลดรูปไม่ได้ กรุณาเชื่อมต่อแล้วเปิดโน้ตอีกครั้ง';}}}
  async function insert(files){for(const file of files){try{const savedRange=q.getSelection(true)||{index:q.getLength()-1,length:0};const image=await space.uploadImage(file);if(token!==mountNumber)return;q.insertEmbed(savedRange.index,'studyImage',image,'user');q.setSelection(savedRange.index+1,0);await hydrate();}catch(err){say(err.message,true);}}}
  bind(document.getElementById('insert-note-image'),'click',()=>document.getElementById('note-image-file').click());bind(document.getElementById('note-image-file'),'change',ev=>{insert([...ev.target.files]);ev.target.value='';});
  bind(q.root,'paste',ev=>{const files=[...(ev.clipboardData?.files||[])];if(files.length){ev.preventDefault();ev.stopImmediatePropagation();insert(files);}},{capture:true});
  bind(q.root,'dragover',ev=>ev.preventDefault());bind(q.root,'drop',ev=>{const files=[...(ev.dataTransfer?.files||[])];if(files.length){ev.preventDefault();ev.stopImmediatePropagation();insert(files);}},{capture:true});
  document.querySelectorAll('[data-note-color],[data-note-bg]').forEach(b=>{bind(b,'mousedown',ev=>ev.preventDefault());bind(b,'click',()=>{const r=q.getSelection(true);const key=b.dataset.noteColor?'color':'background',value=b.dataset.noteColor||b.dataset.noteBg;q.format(key,value==='clear'?false:value,'user');if(r)q.setSelection(r.index,r.length,'silent');});});
  const hydrateChanges=()=>{hydrate();};q.on('text-change',hydrateChanges);listeners.push(()=>q.off('text-change',hydrateChanges));
  bind(document.getElementById('note-undo'),'click',()=>q.history.undo());bind(document.getElementById('note-redo'),'click',()=>q.history.redo());
  for(const [field,key] of [['note-title','title'],['note-tags','tags'],['note-question','question'],['note-answer','answer'],['note-course','course'],['note-lesson','lesson']])bind(document.getElementById(field),field==='note-course'||field==='note-lesson'?'change':'input',ev=>{const live=space.notebook().notes.find(x=>x.id===id);if(!live)return;live[key]=ev.target.value;live.updatedAt=new Date().toISOString();if(key==='course'){live.lesson='';const select=document.getElementById('note-lesson');select.innerHTML='<option value="">ไม่ระบุบทเรียน</option>'+lessons.filter(l=>!live.course||l.course===live.course).map(l=>`<option value="${l.id}">${l.course} · ${e(l.title)}</option>`).join('');}if(key==='lesson'&&live.lesson){live.course=live.lesson.split('-')[0];document.getElementById('note-course').value=live.course;}const ok=space.saveNotebook(space.notebook());say(ok?space.info().status:'ยังไม่บันทึกใน Supabase',!ok);});
  await hydrate();
 }catch(err){say(err.message,true);}
}
function download(name,data,type='application/json'){const u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function exportBook(space){const snapshot=space.snapshot(),images={};for(const id of referencedImages(snapshot.notebook)){const b=await space.image(id);images[id]=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(b);});}download('ru-study-notebook-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({format:'ru-study-notebook',version:1,snapshot,images}));}
export async function notebookAction(action,data,space,progress,render,toast){
 if(!space.info().canEdit){toast('กำลังเชื่อมต่อสมุดจดกับ Supabase กรุณาลองอีกครั้ง');return;}
 const book=space.notebook(),n=book.notes.find(x=>x.id===data.id);
 try{
  if(action==='nb-new'||action==='nb-from-lesson'){const l=lessons.find(x=>x.id===data.lesson);const note=newNote({course:l?.course||course,lesson:l?.id||'',title:l?.title||'โน้ตใหม่'});book.notes.push(note);space.saveNotebook(book);location.hash='#note/'+note.id;}
  if(action==='nb-pin'&&n){n.pinned=!n.pinned;space.saveNotebook(book);render(true);}
  if(action==='nb-archive'&&n){n.archived=!n.archived;space.saveNotebook(book);location.hash='#notes';}
  if(action==='nb-archive-filter'){archived=!archived;render(true);}
  if(action==='nb-review'){reviewing=true;reviewIndex=0;revealed=false;if(location.hash==='#notes')render();else location.hash='#notes';}
  if(action==='nb-review-close'){reviewing=false;render();}
  if(action==='nb-review-next'){reviewIndex++;revealed=false;render(true);}
  if(action==='nb-reveal'){revealed=true;render(true);}
  if(action==='nb-print')window.print();
  if(action==='nb-export'){toast('กำลังรวมโน้ตและรูปภาพ…');await exportBook(space);toast('ส่งออกโน้ตและรูปครบแล้ว');}
  if(action==='nb-import-legacy'){const existing=new Set(book.notes.map(x=>x.id));book.notes.push(...legacyNotes(progress,lessons).filter(x=>!existing.has(x.id)));space.saveNotebook(book);render();toast('คัดลอกแล้ว บันทึกเดิมยังอยู่ครบ');}
 }catch(err){toast(err.message||'ดำเนินการไม่สำเร็จ');}
}
export function notebookSearch(space,value){query=value;document.getElementById('notebook-results').innerHTML=noteCards(findNotes(space.notebook(),{query,course,archived}));}
export function notebookFilter(value){course=value;}
export async function importNotebook(file,space){if(file.size>100*1024*1024)throw Error('ไฟล์สำรองเกิน 100 MB');const data=JSON.parse(await file.text());if(data.format!=='ru-study-notebook'||data.version!==1)throw Error('ไฟล์ไม่ใช่สมุดจด RU Study Planner');for(const v of Object.values(data.images||{}))if(typeof v!=='string'||!/^data:image\/(png|jpeg|webp|gif);base64,/.test(v)||v.length>7100000)throw Error('รูปในไฟล์สำรองไม่ถูกต้อง');if(!confirm('นำเข้าสมุดจดและความคืบหน้าเพื่อแทนที่ฉบับปัจจุบัน? ระบบจะเก็บสำเนาก่อนนำเข้าไว้ในเครื่อง'))return;await space.importSnapshot(data.snapshot,data.images||{});}
